const list = value => value == null ? [] : Array.isArray(value) ? value : [value];
const text = value => typeof value === 'string' ? value : value?._ ?? '';
const feed = $input.first().json.feed;
if (!feed || !Number.isFinite(Date.parse(text(feed.updated)))) throw new Error('Invalid JMA Atom feed');
const candidates = list(feed.entry).flatMap(entry => {
  const links = list(entry.link);
  const sourceUrl = links.map(link => link?.$?.href).find(url => typeof url === 'string' && /^https:\/\/www\.data\.jma\.go\.jp\/developer\/xml\/data\/[A-Za-z0-9_]+_VPWW53_230000\.xml$/.test(url));
  if (!sourceUrl || text(entry.author?.name) !== '名古屋地方気象台') return [];
  const publishedAt = text(entry.updated);
  if (!Number.isFinite(Date.parse(publishedAt))) throw new Error('Invalid bulletin timestamp');
  return [{ sourceUrl, publishedAt, title: text(entry.title) }];
}).sort((a,b) => Date.parse(b.publishedAt) - Date.parse(a.publishedAt) || b.sourceUrl.localeCompare(a.sourceUrl));
return [{json:{feedUpdatedAt:text(feed.updated), candidates}}];

const rows = $input.all();
if (rows.length !== 1 || rows[0].json.recordKey !== 'current:230000') throw new Error('Expected exactly one initialized Aichi state row');
const current = rows[0].json;
const previous = current.payloadJson ? JSON.parse(current.payloadJson) : {};
const seen = new Set(previous.processedUrls ?? []);
if (current.sourceUrl) seen.add(current.sourceUrl);
const candidates = $('Select Aichi bulletins').first().json.candidates;
const candidate = candidates[0];
if (!candidate || seen.has(candidate.sourceUrl)) return [];
if (current.publishedAt && Date.parse(candidate.publishedAt) < Date.parse(current.publishedAt)) return [];
return [{json:{...candidate, processedUrls:[...seen].slice(-199)}}];

const list = value => value == null ? [] : Array.isArray(value) ? value : [value];
const text = value => typeof value === 'string' ? value : value?._ ?? '';
const report = $input.first().json.Report;
if (!report?.Control || !report?.Head) throw new Error('Missing JMA report headers');
if (text(report.Control.Status) !== '通常') return [];
if (text(report.Control.PublishingOffice) !== '名古屋地方気象台' || text(report.Head.Title) !== '愛知県気象警報・注意報') throw new Error('Unexpected warning region or publisher');
const candidate = $('Skip seen or older bulletin').first().json;
const reportDateTime = text(report.Head.ReportDateTime);
if (!Number.isFinite(Date.parse(reportDateTime))) throw new Error('Invalid report date');
const infoType = text(report.Head.InfoType);
if (!['発表','訂正','取消'].includes(infoType)) throw new Error('Unsupported bulletin InfoType: '+infoType);
const invalidated = infoType === '取消';
const municipal = list(report.Body?.Warning).find(w => w?.$?.type === '気象警報・注意報（市町村等）');
if (!invalidated && !municipal) throw new Error('Missing municipality warning section');
const municipalities = invalidated ? [] : list(municipal.Item).map(item => {
 const areaCode = text(item.Area?.Code), areaName = text(item.Area?.Name);
 if (!/^23\d{5}$/.test(areaCode) || !areaName) throw new Error('Invalid Aichi municipality');
 const kinds = list(item.Kind).map(kind => {
  const status = text(kind.Status), code = text(kind.Code), name = text(kind.Name);
  if (!status) throw new Error('Missing warning status');
  if (status !== '発表警報・注意報はなし' && (!code || !name)) throw new Error('Missing warning kind');
  return {code,name,status,details:kind};
 });
 if (!kinds.length) throw new Error('Empty municipality warning status');
 return {areaCode,areaName,kinds};
});
if (!invalidated && !municipalities.some(m => m.areaCode === '2310000' && m.areaName === '名古屋市')) throw new Error('Nagoya status missing');
if (new Set(municipalities.map(m=>m.areaCode)).size !== municipalities.length) throw new Error('Duplicate municipality');
const storedAt = $now.toISO();
const payload = {
 source:'Japan Meteorological Agency', sourceUrl:candidate.sourceUrl,
 publishedAt:candidate.publishedAt, reportDateTime, receivedAt:storedAt,
 infoType, invalidated, interpretation:invalidated?'bulletin_cancelled_status_unknown':'raw_official_statuses',
 headline:text(report.Head.Headline?.Text), municipalities,
 nagoya:municipalities.find(m=>m.areaCode==='2310000') ?? null,
 processedUrls:[...candidate.processedUrls,candidate.sourceUrl].slice(-200),
 control:report.Control, head:report.Head, body:report.Body ?? null,
 backendConnected:false, notificationsSent:false, isDemo:false
};
return [{json:{recordKey:'current:230000', snapshotKey:'bulletin:'+candidate.sourceUrl.split('/').pop(),sourceUrl:candidate.sourceUrl,publishedAt:candidate.publishedAt,reportDateTime,payloadJson:JSON.stringify(payload),storedAt}}];

const list = value => value == null ? [] : Array.isArray(value) ? value : [value];
const text = value => typeof value === 'string' ? value : value?._ ?? '';
const feed = $('Parse earthquake volcano Atom').first().json.feed;
if (!feed || !Number.isFinite(Date.parse(text(feed.updated)))) throw new Error('Invalid JMA earthquake/volcano Atom feed');
const seen = new Set($input.all().map(item => item.json.sourceUrl).filter(Boolean));
const byType = {VTSE41:[],VFVO50:[],VXSE53:[]};
const unique = new Set();
for (const entry of list(feed.entry)) {
 const sourceUrl = list(entry.link).map(link => link?.$?.href).find(url => typeof url === 'string' && /^https:\/\/www\.data\.jma\.go\.jp\/developer\/xml\/data\/[A-Za-z0-9]+_[0-9]+_(VXSE53|VTSE41|VFVO50)_[0-9]{6}\.xml$/.test(url));
 if (!sourceUrl || seen.has(sourceUrl) || unique.has(sourceUrl)) continue;
 unique.add(sourceUrl);
 const publishedAt = text(entry.updated);
 if (!Number.isFinite(Date.parse(publishedAt))) throw new Error('Invalid disaster bulletin timestamp');
 const bulletinType = sourceUrl.split('/').pop().split('_')[2];
 byType[bulletinType].push({sourceUrl,publishedAt,bulletinType,title:text(entry.title)});
}
const selected = [];
for (const type of ['VTSE41','VFVO50','VXSE53']) {
 byType[type].sort((a,b)=>Date.parse(b.publishedAt)-Date.parse(a.publishedAt)||b.sourceUrl.localeCompare(a.sourceUrl));
 selected.push(...byType[type].slice(0,3));
}
return selected.map(json=>({json}));

const list = value => value == null ? [] : Array.isArray(value) ? value : [value];
const text = value => typeof value === 'string' ? value : value?._ ?? '';
const candidate = $('Process each disaster bulletin').item.json;
const report = $input.first().json.Report;
if (!report?.Control || !report?.Head) throw new Error('Missing disaster report headers');
const type = candidate.bulletinType;
const expectedKind = {VXSE53:'地震情報',VTSE41:'津波警報・注意報・予報',VFVO50:'噴火警報・予報'}[type];
if (!expectedKind || text(report.Head.InfoKind) !== expectedKind) throw new Error('Disaster bulletin type mismatch');
const reportDateTime = text(report.Head.ReportDateTime);
if (!Number.isFinite(Date.parse(reportDateTime))) throw new Error('Invalid disaster report date');
const status = text(report.Control.Status);
if (!['通常','訓練','試験'].includes(status)) throw new Error('Unknown disaster bulletin control status');
const ignored = status !== '通常';
const infoType = text(report.Head.InfoType);
if (!['発表','訂正','取消'].includes(infoType)) throw new Error('Unsupported disaster InfoType');
const invalidated = infoType === '取消';
const eventId = text(report.Head.EventID);
if (!ignored && !eventId) throw new Error('Missing disaster event ID');
let details = null;
let aichiMentioned = null;
if (!ignored && !invalidated) {
 const body = report.Body;
 if (!body) throw new Error('Missing disaster body');
 if (type === 'VXSE53') {
  if (!body.Earthquake?.Hypocenter?.Area || !text(body.Earthquake.OriginTime)) throw new Error('Missing earthquake origin or hypocenter');
  const prefectures = list(body.Intensity?.Observation?.Pref);
  aichiMentioned = prefectures.some(p => text(p.Code) === '23' || text(p.Name) === '愛知県');
  details = {kind:'earthquake_information',earthquake:body.Earthquake,intensity:body.Intensity ?? null,observedPrefectures:prefectures,comments:body.Comments ?? null};
 } else if (type === 'VTSE41') {
  const areas = list(body.Tsunami?.Forecast?.Item).map(item => {
   const areaCode=text(item.Area?.Code), areaName=text(item.Area?.Name);
   if (!areaCode || !areaName || !text(item.Category?.Kind?.Code) || !text(item.Category?.Kind?.Name)) throw new Error('Incomplete tsunami area or category');
   return {areaCode,areaName,category:item.Category,firstHeight:item.FirstHeight ?? null,maxHeight:item.MaxHeight ?? null};
  });
  if (!areas.length) throw new Error('Missing tsunami forecast areas');
  aichiMentioned = areas.some(a => ['390','391'].includes(a.areaCode));
  details = {kind:'tsunami_warning_advisory_forecast',areas,earthquakes:list(body.Earthquake),comments:body.Comments ?? null};
 } else {
  const sections = list(body.VolcanoInfo).map(section => ({
   sectionType:section.$?.type ?? '',
   items:list(section.Item).map(item => {
    const areas = list(item.Areas?.Area).map(area => ({code:text(area.Code),name:text(area.Name),raw:area}));
    if (!text(item.Kind?.Code) || !text(item.Kind?.Name) || !areas.length || areas.some(a=>!a.code||!a.name)) throw new Error('Incomplete volcano kind or area');
    return {kind:item.Kind,lastKind:item.LastKind ?? null,areaCodeType:item.Areas?.$?.codeType ?? '',areas};
   })
  }));
  if (!sections.length || sections.every(s=>!s.items.length)) throw new Error('Missing volcano warning sections');
  aichiMentioned = sections.some(s=>s.items.some(i=>i.areaCodeType==='気象・地震・火山情報／市町村等'&&i.areas.some(a=>/^23\d{5}$/.test(a.code))));
  details = {kind:'volcano_warning_forecast',sections,content:body.VolcanoInfoContent ?? null};
 }
}
const storedAt = $now.toISO();
const payload = {
 source:'Japan Meteorological Agency',sourceUrl:candidate.sourceUrl,bulletinType:type,
 scope:'Japan-wide bulletin archive; user-location matching pending',
 publishedAt:candidate.publishedAt,reportDateTime,eventId,serial:text(report.Head.Serial),
 infoType,invalidated,ignored,controlStatus:status,
 interpretation:ignored?'excluded_training_or_test':invalidated?'bulletin_cancelled_status_unknown':'raw_official_bulletin',
 aichiMentioned,aichiMentionMeaning:'Explicit area/observation mention only; not a risk or all-clear assessment',
 headline:text(report.Head.Headline?.Text),details,
 control:report.Control,head:report.Head,body:report.Body ?? null,
 backendConnected:false,notificationsSent:false
};
return [{json:{recordKey:'eqvol:'+candidate.sourceUrl.split('/').pop(),sourceUrl:candidate.sourceUrl,publishedAt:candidate.publishedAt,reportDateTime,payloadJson:JSON.stringify(payload),storedAt}}];

return $input.all().map((item, index) => {
  const row = item.json;
  const bulletin = JSON.parse(row.payloadJson);
  if (!/^https:\/\/www\.data\.jma\.go\.jp\/developer\/xml\/data\/[A-Za-z0-9_]+_(?:VPWW53_230000|(?:VXSE53|VTSE41|VFVO50)_[0-9]+)\.xml$/.test(row.sourceUrl)) throw new Error('Invalid official bulletin source');
  if (bulletin.sourceUrl !== row.sourceUrl || !Number.isFinite(Date.parse(row.publishedAt))) throw new Error('Invalid bulletin identity');
  const deliveryKey = 'jma:' + row.sourceUrl;
  const excluded = bulletin.ignored === true || (bulletin.control?.Status && bulletin.control.Status !== '通常');
  const envelope = {
    schemaVersion: 1, deliveryKey, sourceUrl: row.sourceUrl,
    publishedAt: row.publishedAt, bulletinType: bulletin.bulletinType ?? 'VPWW53',
    purpose: 'warning_ingestion', bulletin
  };
  return {json: {
    deliveryKey, sourceUrl: row.sourceUrl, publishedAt: row.publishedAt,
    payloadJson: JSON.stringify(envelope),
    deliveryStatus: excluded ? 'excluded' : 'pending', acknowledgedAt: ''
  }, pairedItem: {item: index}};
});

return $input.all().map((item, index) => {
  const row = item.json;
  const bulletin = JSON.parse(row.payloadJson);
  if (!/^https:\/\/www\.data\.jma\.go\.jp\/developer\/xml\/data\/[A-Za-z0-9_]+_(?:VPWW53_230000|(?:VXSE53|VTSE41|VFVO50)_[0-9]+)\.xml$/.test(row.sourceUrl)) throw new Error('Invalid official bulletin source');
  if (bulletin.sourceUrl !== row.sourceUrl || !Number.isFinite(Date.parse(row.publishedAt))) throw new Error('Invalid bulletin identity');
  const deliveryKey = 'jma:' + row.sourceUrl;
  const excluded = bulletin.ignored === true || (bulletin.control?.Status && bulletin.control.Status !== '通常');
  const envelope = {
    schemaVersion: 1, deliveryKey, sourceUrl: row.sourceUrl,
    publishedAt: row.publishedAt, bulletinType: bulletin.bulletinType ?? 'VPWW53',
    purpose: 'warning_ingestion', bulletin
  };
  return {json: {
    deliveryKey, sourceUrl: row.sourceUrl, publishedAt: row.publishedAt,
    payloadJson: JSON.stringify(envelope),
    deliveryStatus: excluded ? 'excluded' : 'pending', acknowledgedAt: ''
  }, pairedItem: {item: index}};
});

const config = { enabled: false, endpointUrl: '' };
if (config.enabled !== true) return [];
if (!/^https:\/\/[a-z0-9](?:[a-z0-9.-]*[a-z0-9])?\/[A-Za-z0-9/_-]+$/.test(config.endpointUrl)) throw new Error('Configure an HTTPS ingestion endpoint without credentials, query parameters or fragments');
return [{json: config}];

const response = $input.first().json;
const row = $('Deliver each warning handoff').item.json;
if (response.statusCode < 200 || response.statusCode >= 300 || !Number.isInteger(response.statusCode) || response.body?.accepted !== true || response.body.deliveryKey !== row.deliveryKey) throw new Error('Backend did not durably acknowledge this delivery key');
return [{json: {deliveryKey: row.deliveryKey, deliveryStatus: 'acknowledged', acknowledgedAt: $now.toISO()}}];
